  36 export const useGenerationUIStore = create<GenerationUIState>((set, get) => ({
  37   guidelineState: {},
  38   isBulkGenerating: false,
  39   abortRequested: false,
  40   bulkTotal: 0,
  41   bulkProgress: 0,
  42   bulkStartTime: null,
  43   abortControllers: {},
  44   clipboard: null,
  45 
  46   initializeGuidelines: (key, defaultGuidelines) => {
  47     if (!get().guidelineState[key]) {
  48       const checked: Record<number, boolean> = {};
  49       defaultGuidelines.forEach((g, i) => {
  50         if (g.isDefault) {
  51           checked[i] = true;
  52         }
  53       });
  54       set((state) => ({
  55         guidelineState: {
  56           ...state.guidelineState,
  57           [key]: { checked, custom: [] },
  58         },
  59       }));
  60     }
  61   },
  62 
  63 
  64   handleGuidelineToggle: (key, index, checked) => {
  65     set((state) => {
  66       const keyState = state.guidelineState[key] || { checked: {}, custom: [] };
  67       return {
  68         guidelineState: {
  69           ...state.guidelineState,
  70           [key]: {
  71             ...keyState,
  72             checked: { ...keyState.checked, [index]: checked }
  73           }
  74         }
  75       };
  76     });
  77   },
  78 
  79   addCustomGuideline: (key, guideline) => {
  80     set(state => {
  81       const keyState = state.guidelineState[key] || { checked: {}, custom: [] };
  82       return {
  83         guidelineState: {
  84           ...state.guidelineState,
  85           [key]: {
  86             ...keyState,
  87             custom: [...keyState.custom, guideline]
  88           }
  89         }
  90       }
  91     });
  92   },
  93 
  94   removeCustomGuideline: (key, index) => {
  95     set(state => {
  96       const keyState = state.guidelineState[key];
  97       if (!keyState) return state;
  98       const newCustom = [...keyState.custom];
  99       newCustom.splice(index, 1);
 100       return {
 101         guidelineState: {
 102           ...state.guidelineState,
 103           [key]: { ...keyState, custom: newCustom }
 104         }
 105       }
 106     });
 107   },
 108 
 109   startBulk: (total) => {
 110     set({ isBulkGenerating: true, abortRequested: false, bulkTotal: total, bulkProgress: 0, bulkStartTime: Date.now() });
 111   },
 112 
