 114     set({ isBulkGenerating: false, abortRequested: false, bulkTotal: 0, bulkProgress: 0, bulkStartTime: null });
 115   },
 116 
 117   requestAbort: () => {
 118     set({ abortRequested: true });
 119   },
 120 
 121   incrementProgress: () => {
 122     set(state => ({ bulkProgress: Math.min(state.bulkTotal, state.bulkProgress + 1) }));
 123   },
 124 
 125   registerAbortController: (key, controller) => {
 126     set(state => ({
 127         abortControllers: { ...state.abortControllers, [key]: controller }
 128     }));
 129   },
 130 
 131   removeAbortController: (key) => {
 132     set(state => {
 133         const newControllers = { ...state.abortControllers };
 134         delete newControllers[key];
 135         return { abortControllers: newControllers };
 136     });
 137   },
 138 
 139   cancelGeneration: (key) => {
 140     const controller = get().abortControllers[key];
 141     if (controller) {
 142         controller.abort();
 143         get().removeAbortController(key);
 144     }
 145   },
 146 
 147   copySettings: (settings) => {
 148     set({ clipboard: settings });
 149   },
 150 
 151   resetAll: () => {
 152     Object.values(get().abortControllers).forEach(c => c.abort());
 153     set({
 154       guidelineState: {},
 155       isBulkGenerating: false,
 156       abortRequested: false,
 157       abortControllers: {},
 158       clipboard: null,
 159     });
 160   },
 161 }));
